function nectedFunction(params) {
  const MODULE_ID = "{{.creatingTheModule.output.Body.data.id}}"

  let rows = []
  if (Array.isArray(params)) {
    rows = params
  } else if (params && typeof params === "object") {
    rows =
      params.input ||
      params.data ||
      params.attributes ||
      params.payload ||
      params.body ||
      params.items ||
      params.value ||
      []
    if (!Array.isArray(rows)) {
      const keys = Object.keys(params)
      for (const k of keys) {
        if (Array.isArray(params[k])) {
          rows = params[k]
          break
        }
      }
    }
  }

  const output = []
  for (const data of rows) {
    const rawValues = (data.values || "")
      .split("|")
      .map(function (v) {
        return v.trim()
      })
      .filter(function (v) {
        return v !== ""
      })

    const options = rawValues.map(function (v) {
      let castValue = v
      if (data.dataType === "Numeric") castValue = Number(v)
      else if (data.dataType === "Boolean")
        castValue = v.toLowerCase() === "true"
      return { value: castValue }
    })

    output.push({
      moduleId: MODULE_ID,
      name: data.name,
      dataType: data.dataType,
      options: options,
    })
  }

  return output
}
